{
  "findings": [
    {
      "check_id": "CKV_GCP_25",
      "title": "Ensure Kubernetes Cluster is created with Private cluster enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The cluster does not have `private_cluster_config` enabled, exposing the control plane endpoint to the public internet, which increases the attack surface."
    },
    {
      "check_id": "CKV_GCP_23",
      "title": "Ensure Kubernetes Cluster is created with Alias IP ranges enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The cluster does not use Alias IP ranges (`ip_allocation_policy`), which is the recommended networking mode for VPC-native clusters and provides better scalability and security."
    },
    {
      "check_id": "AVD-GCP-0056",
      "title": "Cluster does not have a network policy enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "Network policy is not enabled in `network_policy`, allowing unrestricted inter-pod communication by default."
    },
    {
      "check_id": "CKV_GCP_19",
      "title": "Ensure Kubernetes Cluster has master authentication disabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "HIGH",
      "explanation": "The `master_auth` block is configured with username/password and client certificates. This is deprecated and insecure; authentication should be handled via IAM or OIDC, and `master_auth` should be removed or disabled."
    },
    {
      "check_id": "CKV_GCP_20",
      "title": "Ensure Kubernetes Cluster has legacy ABAC disabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "HIGH",
      "explanation": "`enable_legacy_abac` is set to true. Legacy ABAC is deprecated and less secure than RBAC; it should be disabled."
    },
    {
      "check_id": "CKV_GCP_21",
      "title": "Ensure Kubernetes Cluster has Kubernetes Alpha disabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "`enable_kubernetes_alpha` is set to true. Alpha features are unstable and may contain security vulnerabilities; they should be disabled in production."
    }
  ],
  "patched_code": "resource \"google_container_cluster\" \"k8sexample\" {\n  name               = \"${var.vault_user}-k8s-cluster\"\n  description        = \"example k8s cluster\"\n  zone               = \"${var.gcp_zone}\"\n  initial_node_count = \"${var.initial_node_count}\"\n  enable_kubernetes_alpha = \"false\"\n  enable_legacy_abac = \"false\"\n  \n  # CKV_GCP_19: Remove insecure master_auth block\n  # master_auth {\n  #   username = \"${var.master_username}\"\n  #   password = \"${var.master_password}\"\n  #   client_certificate_config {\n  #     issue_client_certificate = true\n  #   }\n  # }\n\n  # CKV_GCP_25: Enable private cluster\n  private_cluster_config {\n    enable_private_nodes = true\n    enable_private_endpoint = true\n    master_ipv4_cidr_block = \"172.16.0.0/28\"\n  }\n\n  # CKV_GCP_23: Enable Alias IP ranges\n  ip_allocation_policy {\n    cluster_secondary_range_name = \"pods\"\n    services_secondary_range_name = \"services\"\n  }\n\n  # AVD-GCP-0056: Enable network policy\n  network_policy {\n    enabled = true\n  }\n\n  node_config {\n    machine_type = \"${var.node_machine_type}\"\n    disk_size_gb = \"${var.node_disk_size}\"\n    oauth_scopes = [\n      \"https://www.googleapis.com/auth/compute\",\n      \"https://www.googleapis.com/auth/devstorage.read_only\",\n      \"https://www.googleapis.com/auth/logging.write\",\n      \"https://www.googleapis.com/auth/monitoring\"\n    ]\n  }\n}",
  "fix_summary": "Disabled insecure features (legacy ABAC, Kubernetes Alpha) and removed the deprecated master_auth block. Enabled private cluster configuration, alias IP ranges, and network policy to harden the cluster's network security posture."
}
